insert into public.parts (id, model, topic_id, name, side, blood, sort_order, explanation, exam_pearl)
values ('torso-diaphragm', 'torso', 'respiratory', 'Diaphragm', null, null, 5, 'A dome-shaped sheet of muscle between the chest and abdomen. When it contracts it flattens, the chest gets bigger, pressure inside drops, and air flows in.', 'Breathing in is active; quiet breathing out is passive. It''s Boyle''s law: bigger volume, lower pressure. The phrenic nerve controls the diaphragm.')
